// Normalise the incoming note payload. Accepts POSTs from any source —
// coach tooling, the Rails admin, Zapier, or a Fathom webhook relay — as long
// as it carries the note text and a way to identify the client:
//   { user_id? , email? , note_text, source?, session_date?, coach?, external_ref? }
// Fathom-style payloads: map summary/transcript into note_text and the
// attendee email into email before calling this webhook (or extend this node).
const results = [];
for (const item of $input.all()) {
  const b = (item.json.body && (item.json.body.record ?? item.json.body)) || item.json;
  const text = String(b.note_text ?? b.summary ?? b.text ?? '').trim();
  if (text.length < 20) continue; // nothing clinically useful to extract
  const userId = Number(b.user_id ?? b.app_user_id ?? NaN);
  // sanitise email for safe SQL inlining (identifier lookup only)
  const email = String(b.email ?? '').toLowerCase().replace(/[^a-z0-9@._+-]/g, '');
  if (!Number.isInteger(userId) && !email) continue;
  const src = ['individual', 'group', 'intake', 'other'].includes(b.source) ? b.source : 'individual';
  results.push({
    json: {
      user_id: Number.isInteger(userId) ? userId : null,
      email,
      source: src,
      session_date: /^\d{4}-\d{2}-\d{2}/.test(String(b.session_date ?? '')) ? String(b.session_date).slice(0, 10) : null,
      coach: String(b.coach ?? '').slice(0, 200),
      external_ref: String(b.external_ref ?? b.call_id ?? '').slice(0, 200),
      note_text: text.slice(0, 20000),
    },
  });
}
return results;

// Shape + escape everything for safe SQL inlining, and build the vector-store
// content string (summary + tags — NEVER the raw note text).
const esc = (s) => String(s ?? '').replace(/'/g, "''");
const arr = (a) => '{' + (a ?? []).map((x) => '"' + esc(x).replace(/"/g, '') + '"').join(',') + '}';
const results = [];
for (const item of $input.all()) {
  const out = item.json.output ?? item.json;
  const meta = $('Normalize note payload').itemMatching(item.index)?.json ?? {};
  const uid = Number($('Resolve user').itemMatching(item.index)?.json?.user_id ?? NaN);
  if (!Number.isInteger(uid)) continue; // client not found -> drop (no orphan notes)
  const risk = ['none', 'monitor', 'elevated'].includes(out.risk) ? out.risk : 'none';
  const vectorText = `${out.summary}\nThemes: ${(out.themes ?? []).join(', ')}\nFocus next: ${(out.focus_areas ?? []).join(', ')}`;
  results.push({
    json: {
      user_id: uid,
      source: meta.source,
      session_date_sql: meta.session_date ? `'${meta.session_date}'` : 'NULL',
      coach: esc(meta.coach),
      external_ref: esc(meta.external_ref),
      raw_text: esc(meta.note_text),
      summary: esc(out.summary),
      themes: arr(out.themes),
      concerns: arr(out.concerns),
      wins: arr(out.wins),
      focus_areas: arr(out.focus_areas),
      risk,
      vector_text: vectorText,
    },
  });
}
return results;

